    fn compaction_commit_fingerprint_for_test(
        commit: &meerkat_core::TranscriptRewriteCommit,
    ) -> String {
        use sha2::{Digest, Sha256};
        use std::fmt::Write as _;

        #[derive(serde::Serialize)]
        struct Fingerprint<'a> {
            selection: &'a TranscriptRewriteSelection,
            original_span_digest: &'a str,
            replacement_digest: &'a str,
            messages_before: usize,
            messages_after: usize,
            actor: &'a Option<String>,
        }

        let canonical = serde_json::to_vec(&Fingerprint {
            selection: &commit.selection,
            original_span_digest: &commit.original_span_digest,
            replacement_digest: &commit.replacement_digest,
            messages_before: commit.messages_before,
            messages_after: commit.messages_after,
            actor: &commit.actor,
        })
        .expect("compaction fingerprint should serialize");
        let mut fingerprint = String::from("sha256:");
        for byte in Sha256::digest(canonical) {
            write!(&mut fingerprint, "{byte:02x}").expect("writing a digest to String cannot fail");
        }
        fingerprint
    }

    fn without_session_owned_metadata(session: &Session) -> Session {
        let mut document = serde_json::to_value(session).expect("session should serialize");
        let metadata = document
            .get_mut("metadata")
            .and_then(serde_json::Value::as_object_mut)
            .expect("session metadata should be an object");
        metadata.remove(SESSION_METADATA_KEY);
        metadata.remove(meerkat_core::SESSION_BUILD_STATE_KEY);
        serde_json::from_value(document).expect("session without owned metadata should deserialize")
    }

    #[tokio::test]
    async fn idle_turn_finalization_gate_keys_are_reaped_without_splitting_overlap() {
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::new(MemoryStore::new()),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        );
        let first_session_id = SessionId::new();
        let first_gate = service
            .turn_finalization_gate_for_session(&first_session_id)
            .await;
        let overlapping_gate = service
            .turn_finalization_gate_for_session(&first_session_id)
            .await;
        assert!(Arc::ptr_eq(&first_gate, &overlapping_gate));
        drop(first_gate);
        drop(overlapping_gate);

        let second_session_id = SessionId::new();
        let second_gate = service
            .turn_finalization_gate_for_session(&second_session_id)
            .await;
        let gates = service.turn_finalization_gates.lock().await;
        assert!(!gates.contains_key(&first_session_id));
        let retained_second = gates
            .get(&second_session_id)
            .and_then(std::sync::Weak::upgrade)
            .expect("live gate should remain upgradeable");
        assert!(Arc::ptr_eq(&second_gate, &retained_second));
    }

    struct FailOneBoundedReadBlobStore {
        inner: FsBlobStore,
        fail_next_bounded_read: AtomicBool,
    }

    impl FailOneBoundedReadBlobStore {
        fn new(root: std::path::PathBuf) -> Self {
            Self {
                inner: FsBlobStore::new(root),
                fail_next_bounded_read: AtomicBool::new(true),
            }
        }
    }

    #[async_trait::async_trait]
    impl BlobStore for FailOneBoundedReadBlobStore {
        async fn put_image(
            &self,
            media_type: &str,
            data: &str,
        ) -> Result<meerkat_core::BlobRef, meerkat_core::BlobStoreError> {
            self.inner.put_image(media_type, data).await
        }

        async fn get(
            &self,
            blob_id: &meerkat_core::BlobId,
        ) -> Result<meerkat_core::BlobPayload, meerkat_core::BlobStoreError> {
            self.inner.get(blob_id).await
        }

        async fn get_with_encoded_limit(
            &self,
            blob_id: &meerkat_core::BlobId,
            max_encoded_bytes: usize,
        ) -> Result<meerkat_core::BlobPayload, meerkat_core::BlobStoreError> {
            if self.fail_next_bounded_read.swap(false, Ordering::AcqRel) {
                return Err(meerkat_core::BlobStoreError::ReadFailed(
                    "synthetic crash after durable put before readback/reducer".to_string(),
                ));
            }
            self.inner
                .get_with_encoded_limit(blob_id, max_encoded_bytes)
                .await
        }

        async fn delete(
            &self,
            blob_id: &meerkat_core::BlobId,
        ) -> Result<(), meerkat_core::BlobStoreError> {
            self.inner.delete(blob_id).await
        }

        fn is_persistent(&self) -> bool {
            true
        }
    }

    #[test]
    fn durable_sync_unsupported_matches_typed_variant_not_substring() {
        // Typed variant from the default SessionAgent capability is detected.
        let unsupported = SessionError::Agent(AgentError::DurableSnapshotSyncUnsupported);
        assert!(is_durable_session_sync_unsupported(&unsupported));

        // An unrelated ConfigError (even one whose text happens to mention the
        // phrase) must NOT be classified as unsupported — the predicate is
        // typed, not substring-based.
        let config_error = SessionError::Agent(AgentError::ConfigError(
            "durable session snapshot synchronization is not supported by this session agent"
                .to_string(),
        ));
        assert!(!is_durable_session_sync_unsupported(&config_error));
    }

    #[tokio::test]
    async fn append_and_project_event_propagates_durable_append_failure_with_no_hole()
    -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        // Gate (row #131): the canonical durable event log is the truth that
        // replay APIs later expose as surface-visible state, so a dropped
        // append is a terminal fault — it leaves a sequence hole. The OLD
        // behavior swallowed the append failure into `tracing::warn!` and
        // returned (), laundering a durability hole into silent success.
        let event_store = Arc::new(RecordingEventStore::default());
        let event_store_trait: Arc<dyn EventStore> = event_store.clone();
        let dir = tempfile::tempdir()?;
        let projector = Arc::new(SessionProjector::new(dir.path().join(".rkat")));
        let session_id = SessionId::new();
        let projection_faults: EventProjectionFaultRegistry = Arc::new(Mutex::new(HashMap::new()));
        let projection_gates: EventProjectionGateRegistry = Arc::new(Mutex::new(HashMap::new()));

        let started = || {
            meerkat_core::event::EventEnvelope::new_session(
                session_id.clone(),
                0,
                None,
                AgentEvent::RunStarted {
                    session_id: session_id.clone(),
                    input: meerkat_core::types::RunInput::Content {
                        content: ContentInput::Text("seed".to_string()),
                    },
                },
            )
        };

        // A failing durable append must surface a typed SessionError::Store,
        // not a fabricated success.
        event_store.fail_appends();
        let err = append_and_project_event(
            &event_store_trait,
            &projector,
            &session_id,
            started(),
            &projection_faults,
            &projection_gates,
        )
        .await
        .expect_err("durable append failure must surface a typed terminal error");
        assert!(
            matches!(err, SessionError::Store(_)),
            "unexpected error: {err}"
        );

        // Replay shows no hole: nothing was committed to the canonical log.
        assert_eq!(event_store.last_seq(&session_id).await?, 0);

        // The terminal latch remains absorbing even if the backing store later
        // becomes writable again.
        event_store.allow_appends();
        let second = append_and_project_event(
            &event_store_trait,
            &projector,
            &session_id,
            started(),
            &projection_faults,
            &projection_gates,
        )
        .await;
        assert!(
            second.is_err(),
            "an append failure is absorbing even if the backing store later recovers"
        );
        let replayed = event_store.read_from(&session_id, 0).await?;
        assert!(replayed.is_empty());
        Ok(())
    }

    #[tokio::test]
    async fn halted_event_projection_fails_replay_closed()
    -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        // Gate: a detached projection task that halts on a durable append
        // failure must not terminate the typed fault in a log line. The fault
        // is recorded in the service's typed fault registry and replay reads
        // fail closed on it instead of serving a stream with a silent hole.
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let event_store = Arc::new(RecordingEventStore::default());
        let event_store_trait: Arc<dyn EventStore> = event_store.clone();
        let dir = tempfile::tempdir()?;
        let projector = Arc::new(SessionProjector::new(dir.path().join(".rkat")));
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        )
        .with_event_projection(event_store_trait.clone(), Arc::clone(&projector));

        let session_id = SessionId::new();
        event_store.fail_appends();

        // Drive the create-time projection conduit against the service's typed
        // fault registry, exactly as `install_create_time_event_projection`
        // wires it for real sessions.
        let (projection_tx, projection_rx) = mpsc::channel(4);
        let (session_tx, session_rx) = watch::channel(Some(session_id.clone()));
        let task = tokio::spawn(project_create_time_events(
            event_store_trait,
            projector,
            projection_rx,
            session_rx,
            None,
            CreateTimeEventProjectionLifecycle {
                projection_faults: Arc::clone(&service.event_projection_faults),
                projection_gates: Arc::clone(&service.event_projection_gates),
                drain_registration: None,
            },
        ));
        projection_tx
            .send(meerkat_core::event::EventEnvelope::new_session(
                session_id.clone(),
                0,
                None,
                AgentEvent::RunStarted {
                    session_id: session_id.clone(),
                    input: meerkat_core::types::RunInput::Content {
                        content: ContentInput::Text("seed".to_string()),
                    },
                },
            ))
            .await?;
        drop(projection_tx);
        drop(session_tx);
        task.await?;

        let latest_err = service
            .event_log_latest_seq(&session_id)
            .await
            .expect_err("latest cursor after a halted projection must fail closed");
        assert!(
            matches!(&latest_err, SessionError::Store(source)
                if source.downcast_ref::<EventProjectionHalted>().is_some()),
            "expected typed EventProjectionHalted latest-cursor fault, got: {latest_err}"
        );

        let err = service
            .event_log_read_from(&session_id, 0)
            .await
            .expect_err("replay after a halted projection must fail closed");
        match err {
            SessionError::Store(source) => {
                assert!(
                    source.downcast_ref::<EventProjectionHalted>().is_some(),
                    "expected typed EventProjectionHalted fault, got: {source}"
                );
            }
            other => panic!("expected SessionError::Store, got: {other}"),
        }

        // Unrelated sessions still replay normally.
        let other_session = SessionId::new();
        assert!(
            service
                .event_log_read_from(&other_session, 0)
                .await?
                .is_some_and(|events| events.is_empty())
        );
        Ok(())
    }

    #[tokio::test]
    async fn generation_cutover_drain_waits_for_create_time_projection()
    -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let event_store = Arc::new(PausingAppendEventStore::default());
        let event_store_trait: Arc<dyn EventStore> = event_store.clone();
        let dir = tempfile::tempdir()?;
        let service = Arc::new(
            PersistentSessionService::new(
                DummyBuilder,
                4,
                store,
                Arc::new(InMemoryRuntimeStore::new()),
                memory_blob_store(),
            )
            .with_event_projection(
                event_store_trait,
                Arc::new(SessionProjector::new(dir.path().join(".rkat"))),
            ),
        );
        let session_id = SessionId::new();
        let mut request = CreateSessionRequest {
            injected_context: Vec::new(),
            model: "projection-drain-probe".to_string(),
            prompt: ContentInput::Text("seed".to_string()),
            system_prompt: meerkat_core::SystemPromptOverride::Inherit,
            max_tokens: None,
            event_tx: None,
            initial_turn: InitialTurnPolicy::Defer,
            deferred_prompt_policy: DeferredPromptPolicy::Discard,
            build: None,
            labels: None,
        };
        let CreateTimeEventProjection {
            session_tx,
            drain_rx: _drain_rx,
        } = service
            .install_create_time_event_projection(&mut request, Some(&session_id))
            .await
            .expect("persistent event projection is configured");
        let projection_tx = request
            .event_tx
            .take()
            .expect("create-time projection sender installed");
        assert!(
            session_tx.send(Some(session_id.clone())).is_ok(),
            "create-time projector still owns the session-id receiver"
        );
        projection_tx
            .send(meerkat_core::event::EventEnvelope::new_session(
                session_id.clone(),
                1,
                None,
                AgentEvent::RunStarted {
                    session_id: session_id.clone(),
                    input: meerkat_core::types::RunInput::Content {
                        content: ContentInput::Text("seed".to_string()),
                    },
                },
            ))
            .await?;
        drop(projection_tx);
        drop(session_tx);

        event_store.wait_for_append().await;
        let drain_service = Arc::clone(&service);
        let drain_session_id = session_id.clone();
        let mut drain_task = tokio::spawn(async move {
            drain_service
                .event_log_await_projection_drain(&drain_session_id)
                .await
        });
        assert!(
            tokio::time::timeout(std::time::Duration::from_millis(100), &mut drain_task)
                .await
                .is_err(),
            "generation cutover must remain blocked while a create-time append is in flight"
        );

        event_store.release_append();
        let drained = tokio::time::timeout(std::time::Duration::from_secs(5), &mut drain_task)
            .await
            .expect("projection drain completed after the append gate opened")
            .expect("projection drain task joined")?;
        assert!(drained, "the create-time projector was part of the drain");
        let final_seq = event_store.last_seq(&session_id).await?;
        assert_eq!(final_seq, 1);
        tokio::task::yield_now().await;
        assert_eq!(
            event_store.last_seq(&session_id).await?,
            final_seq,
            "no old-incarnation event may append after the drain returns"
        );
        Ok(())
    }

    #[tokio::test]
    async fn lagged_event_projection_persists_halt_before_renumbering_later_events()
    -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        let dir = tempfile::tempdir()?;
        let session_id = SessionId::new();
        let concrete_store = Arc::new(crate::event_store::FileEventStore::new(
            dir.path().join("events"),
        ));
        let event_store: Arc<dyn EventStore> = concrete_store.clone();
        let projector = Arc::new(SessionProjector::new(dir.path().join(".rkat")));
        let faults: EventProjectionFaultRegistry = Arc::new(Mutex::new(HashMap::new()));
        let gates: EventProjectionGateRegistry = Arc::new(Mutex::new(HashMap::new()));

        let gap = meerkat_core::event::EventEnvelope::new_session(
            session_id.clone(),
            0,
            None,
            AgentEvent::StreamTruncated {
                reason: meerkat_core::event::StreamTruncationReason::StreamLagged { dropped: 17 },
            },
        );
        let later = meerkat_core::event::EventEnvelope::new_session(
            session_id.clone(),
            99,
            None,
            AgentEvent::StreamTruncated {
                reason: meerkat_core::event::StreamTruncationReason::ChannelFull,
            },
        );
        let stream: meerkat_core::comms::EventStream =
            Box::pin(futures::stream::iter(vec![gap, later]));

        project_session_event_stream(
            event_store,
            projector,
            session_id.clone(),
            stream,
            Arc::clone(&faults),
            gates,
        )
        .await;

        let marker = concrete_store
            .projection_halt(&session_id)
            .await?
            .expect("lag must persist a durable projection halt");
        assert!(marker.reason.contains("17 canonical events were dropped"));
        assert!(
            concrete_store.read_from(&session_id, 0).await?.is_empty(),
            "neither the synthetic marker nor later events may be renumbered into the durable log"
        );
        let faults = faults.lock().await;
        let cause = faults.get(&session_id).expect("typed in-process fault");
        assert!(matches!(
            cause.as_ref(),
            SessionError::Store(source)
                if source.downcast_ref::<SessionEventProjectionLagged>().is_some()
        ));
        Ok(())
    }

    #[tokio::test]
    async fn durable_event_projection_halt_marker_fails_replay_after_restart()
    -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        // Gate: the replay stop condition must not be only process-local. A
        // restarted service over the same file event store must observe the
        // durable halt marker before it serves any event-log replay.
        let dir = tempfile::tempdir()?;
        let event_root = dir.path().join("events");
        let session_id = SessionId::new();
        let initial_store = crate::event_store::FileEventStore::new(&event_root);
        initial_store
            .append(
                &session_id,
                &[AgentEvent::StreamTruncated {
                    reason: meerkat_core::event::StreamTruncationReason::ChannelFull,
                }],
            )
            .await?;
        initial_store
            .record_projection_halt(&session_id, "injected durable append failure")
            .await?;
        assert_eq!(initial_store.last_seq(&session_id).await?, 1);

        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let restarted_concrete = Arc::new(crate::event_store::FileEventStore::new(&event_root));
        let restarted_event_store: Arc<dyn EventStore> = restarted_concrete.clone();
        let projector = Arc::new(SessionProjector::new(dir.path().join(".rkat")));

        let stream_faults: EventProjectionFaultRegistry = Arc::new(Mutex::new(HashMap::new()));
        let stream_gates: EventProjectionGateRegistry = Arc::new(Mutex::new(HashMap::new()));
        let later_stream: meerkat_core::comms::EventStream = Box::pin(futures::stream::iter(vec![
            meerkat_core::event::EventEnvelope::new_session(
                session_id.clone(),
                2,
                None,
                AgentEvent::StreamTruncated {
                    reason: meerkat_core::event::StreamTruncationReason::ChannelFull,
                },
            ),
        ]));
        project_session_event_stream(
            restarted_event_store.clone(),
            projector.clone(),
            session_id.clone(),
            later_stream,
            stream_faults,
            stream_gates,
        )
        .await;
        assert_eq!(
            restarted_concrete.last_seq(&session_id).await?,
            1,
            "restart projector appended past a durable terminal marker"
        );

        let create_faults: EventProjectionFaultRegistry = Arc::new(Mutex::new(HashMap::new()));
        let create_gates: EventProjectionGateRegistry = Arc::new(Mutex::new(HashMap::new()));
        let (projection_tx, projection_rx) = mpsc::channel(1);
        let (_session_tx, session_rx) = watch::channel(Some(session_id.clone()));
        let create_task = tokio::spawn(project_create_time_events(
            restarted_event_store.clone(),
            projector.clone(),
            projection_rx,
            session_rx,
            None,
            CreateTimeEventProjectionLifecycle {
                projection_faults: create_faults,
                projection_gates: create_gates,
                drain_registration: None,
            },
        ));
        projection_tx
            .send(meerkat_core::event::EventEnvelope::new_session(
                session_id.clone(),
                3,
                None,
                AgentEvent::StreamTruncated {
                    reason: meerkat_core::event::StreamTruncationReason::ChannelFull,
                },
            ))
            .await?;
        drop(projection_tx);
        create_task.await?;
        assert_eq!(
            restarted_concrete.last_seq(&session_id).await?,
            1,
            "restart create-time projector appended past a durable terminal marker"
        );

        let restarted = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        )
        .with_event_projection(restarted_event_store, projector);

        let latest_err = restarted
            .event_log_latest_seq(&session_id)
            .await
            .expect_err("durable halt marker must fail latest cursor after restart");
        assert!(
            matches!(&latest_err, SessionError::Store(source)
                if source.downcast_ref::<EventProjectionHalted>().is_some()),
            "expected typed EventProjectionHalted latest-cursor fault after restart, got: {latest_err}"
        );

        let err = restarted
            .event_log_read_from(&session_id, 0)
            .await
            .expect_err("durable halt marker must fail replay after restart");
        match err {
            SessionError::Store(source) => {
                let halted = source
                    .downcast_ref::<EventProjectionHalted>()
                    .expect("expected typed EventProjectionHalted replay error");
                let cause = halted.cause.as_ref();
                assert!(
                    matches!(cause, SessionError::Store(marker)
                        if marker.downcast_ref::<DurableEventProjectionHaltMarker>().is_some()),
                    "expected durable marker source, got: {cause}"
                );
            }
            other => panic!("expected SessionError::Store, got: {other}"),
        }
        Ok(())
    }

    #[tokio::test]
    async fn projection_latch_precedes_blocking_marker_and_fences_concurrent_append()
    -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        let session_store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let concrete_store = Arc::new(BlockingProjectionHaltStore::default());
        let event_store: Arc<dyn EventStore> = concrete_store.clone();
        let dir = tempfile::tempdir()?;
        let projector = Arc::new(SessionProjector::new(dir.path().join(".rkat")));
        let service = Arc::new(
            PersistentSessionService::new(
                DummyBuilder,
                4,
                session_store,
                Arc::new(InMemoryRuntimeStore::new()),
                memory_blob_store(),
            )
            .with_event_projection(event_store.clone(), projector.clone()),
        );
        let session_id = SessionId::new();

        let record_faults = Arc::clone(&service.event_projection_faults);
        let record_gates = Arc::clone(&service.event_projection_gates);
        let record_store = event_store.clone();
        let record_session_id = session_id.clone();
        let record_task = tokio::spawn(async move {
            record_event_projection_fault(
                &record_faults,
                &record_gates,
                &record_store,
                &record_session_id,
                SessionError::Store(Box::new(EventStoreError::Store(
                    "synthetic projection gap".to_string(),
                ))),
            )
            .await;
        });

        concrete_store.wait_for_marker_write().await;

        // The marker store is deliberately blocked, yet replay must observe
        // the process-local terminal latch immediately rather than waiting for
        // durable I/O to finish.
        let replay = tokio::time::timeout(
            std::time::Duration::from_millis(250),
            service.event_log_read_from(&session_id, 0),
        )
        .await
        .expect("replay waited on the blocked marker write")
        .expect_err("replay crossed an already-published terminal latch");
        assert!(matches!(replay, SessionError::Store(_)));

        let append_store = event_store.clone();
        let append_projector = projector.clone();
        let append_faults = Arc::clone(&service.event_projection_faults);
        let append_gates = Arc::clone(&service.event_projection_gates);
        let append_session_id = session_id.clone();
        let append_task = tokio::spawn(async move {
            append_and_project_event(
                &append_store,
                &append_projector,
                &append_session_id,
                meerkat_core::event::EventEnvelope::new_session(
                    append_session_id.clone(),
                    1,
                    None,
                    AgentEvent::StreamTruncated {
                        reason: meerkat_core::event::StreamTruncationReason::ChannelFull,
                    },
                ),
                &append_faults,
                &append_gates,
            )
            .await
        });
        tokio::task::yield_now().await;
        assert!(
            !append_task.is_finished(),
            "same-session append must wait behind latch+marker publication"
        );

        concrete_store.release_marker_write();
        record_task.await?;
        assert!(
            append_task.await?.is_err(),
            "append admitted after the terminal latch"
        );
        assert_eq!(concrete_store.last_seq(&session_id).await?, 0);
        Ok(())
    }

    #[tokio::test]
    async fn durable_projection_halt_rejects_resume_before_agent_build()
    -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        let dir = tempfile::tempdir()?;
        let session_id = SessionId::new();
        let event_store = Arc::new(crate::event_store::FileEventStore::new(
            dir.path().join("events"),
        ));
        event_store
            .record_projection_halt(&session_id, "restart projection gap")
            .await?;
        let event_store: Arc<dyn EventStore> = event_store;
        let builds = Arc::new(AtomicUsize::new(0));
        let service = PersistentSessionService::new(
            CountingBuilder {
                builds: Arc::clone(&builds),
            },
            4,
            Arc::new(MemoryStore::new()),
            Arc::new(InMemoryRuntimeStore::new()),
            memory_blob_store(),
        )
        .with_event_projection(
            event_store,
            Arc::new(SessionProjector::new(dir.path().join(".rkat"))),
        );

        let error = service
            .create_session(resume_request(Session::with_id(session_id)))
            .await
            .expect_err("resume crossed an absorbing projection halt");
        assert!(matches!(error, SessionError::Store(_)));
        assert_eq!(
            builds.load(Ordering::Acquire),
            0,
            "resume reached the inner agent builder before projector admission"
        );
        Ok(())
    }

    struct RecordingEventStore {
        events: Mutex<HashMap<SessionId, Vec<StoredEvent>>>,
        projection_halts: Mutex<HashMap<SessionId, crate::event_store::EventProjectionHaltMarker>>,
        notify: tokio::sync::Notify,
        fail_appends: AtomicBool,
        rewrite_append_calls: AtomicUsize,
        fail_rewrite_append_call: AtomicUsize,
    }

    impl Default for RecordingEventStore {
        fn default() -> Self {
            Self {
                events: Mutex::new(HashMap::new()),
                projection_halts: Mutex::new(HashMap::new()),
                notify: tokio::sync::Notify::new(),
                fail_appends: AtomicBool::new(false),
                rewrite_append_calls: AtomicUsize::new(0),
                fail_rewrite_append_call: AtomicUsize::new(0),
            }
        }
    }

    impl RecordingEventStore {
        fn fail_appends(&self) {
            self.fail_appends.store(true, Ordering::Release);
        }

        fn allow_appends(&self) {
            self.fail_appends.store(false, Ordering::Release);
        }

        fn fail_rewrite_append_call(&self, call: usize) {
            self.fail_rewrite_append_call.store(call, Ordering::Release);
        }

        async fn wait_for_seq(&self, session_id: &SessionId, target_seq: u64) {
            tokio::time::timeout(std::time::Duration::from_secs(10), async {
                loop {
                    if self.last_seq(session_id).await.unwrap() >= target_seq {
                        return;
                    }
                    // `notify_waiters` does not retain a permit when an append
                    // lands between the sequence check and waiter
                    // registration. Polling keeps this test helper immune to
                    // that lost-wakeup window.
                    tokio::time::sleep(std::time::Duration::from_millis(10)).await;
                }
            })
            .await
            .expect("event store projection did not reach expected sequence");
        }
    }

    async fn read_projected_events_after(events_path: &std::path::Path, expected: &str) -> String {
        tokio::time::timeout(std::time::Duration::from_secs(10), async {
            loop {
                if let Ok(projected) = tokio::fs::read_to_string(events_path).await
                    && projected.contains(expected)
                {
                    return projected;
                }
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("projected events.jsonl did not contain expected event")
    }

    #[async_trait::async_trait]
    impl EventStore for RecordingEventStore {
        async fn append_envelopes(
            &self,
            session_id: &SessionId,
            envelopes: &[meerkat_core::event::EventEnvelope<AgentEvent>],
        ) -> Result<u64, EventStoreError> {
            let receipts: Vec<_> = envelopes
                .iter()
                .filter_map(|envelope| match &envelope.payload {
                    AgentEvent::TranscriptRewriteAuditReceiptCommitted {
                        session_id,
                        receipt,
                        final_assistant_text,
                    } => Some((session_id, receipt, final_assistant_text)),
                    _ => None,
                })
                .collect();
            if let [(receipt_session_id, receipt, final_assistant_text)] = receipts.as_slice() {
                if envelopes.len() != 1 || *receipt_session_id != session_id {
                    return Err(EventStoreError::Store(
                        "generic transcript rewrite receipt batches are forbidden".to_string(),
                    ));
                }
                return self
                    .append_transcript_rewrite_receipt_exact(
                        session_id,
                        receipt,
                        final_assistant_text.as_deref(),
                    )
                    .await
                    .map(|result| result.stored_event().seq);
            }
            if !receipts.is_empty() {
                return Err(EventStoreError::Store(
                    "generic transcript rewrite receipt batches are forbidden".to_string(),
                ));
            }
            let contains_interaction_terminal = envelopes.iter().any(|envelope| {
                matches!(
                    envelope.source,
                    meerkat_core::event::EventSourceIdentity::Interaction { .. }
                ) || matches!(
                    envelope.payload,
                    AgentEvent::InteractionComplete { .. }
                        | AgentEvent::InteractionCallbackPending { .. }
                        | AgentEvent::InteractionFailed { .. }
                )
            });
            if contains_interaction_terminal {
                let [envelope] = envelopes else {
                    return Err(EventStoreError::Store(
                        "interaction terminals must use a singleton exact append".to_string(),
                    ));
                };
                let meerkat_core::event::EventSourceIdentity::Interaction { interaction_id } =
                    &envelope.source
                else {
                    return Err(EventStoreError::Store(
                        "interaction terminal payload requires Interaction source".to_string(),
                    ));
                };
                crate::event_store::validate_exact_interaction_terminal(*interaction_id, envelope)?;
                return self
                    .append_interaction_terminal_exact(session_id, *interaction_id, envelope)
                    .await
                    .map(|result| result.stored_event().seq);
            }
            if self.fail_appends.load(Ordering::Acquire) {
                return Err(EventStoreError::Store(
                    "synthetic transcript rewrite audit append failure".to_string(),
                ));
            }
            if envelopes.iter().any(|envelope| {
                matches!(
                    envelope.payload,
                    AgentEvent::TranscriptRewriteCommitted { .. }
                )
            }) {
                let call = self.rewrite_append_calls.fetch_add(1, Ordering::AcqRel) + 1;
                if self.fail_rewrite_append_call.load(Ordering::Acquire) == call {
                    return Err(EventStoreError::Store(
                        "synthetic transcript rewrite audit append failure".to_string(),
                    ));
                }
            }
            let mut all_events = self.events.lock().await;
            let session_events = all_events.entry(session_id.clone()).or_default();
            for envelope in envelopes {
                let seq = session_events.len() as u64 + 1;
                session_events.push(StoredEvent {
                    seq,
                    schema_version: EVENT_SCHEMA_VERSION,
                    timestamp: meerkat_core::time_compat::SystemTime::now(),
                    source: envelope.source.clone(),
                    mob_id: envelope.mob_id.clone(),
                    stream_seq: envelope.seq,
                    event: envelope.payload.clone(),
                });
            }
            let last_seq = session_events.len() as u64;
            drop(all_events);
            self.notify.notify_waiters();
            Ok(last_seq)
        }

        async fn append_transcript_rewrite_receipt_exact(
            &self,
            session_id: &SessionId,
            receipt: &meerkat_core::TranscriptRewriteAuditReceiptBatch,
            final_assistant_text: Option<&str>,
        ) -> Result<crate::event_store::ExactTranscriptRewriteReceiptAppend, EventStoreError>
        {
            if self.fail_appends.load(Ordering::Acquire) {
                return Err(EventStoreError::Store(
                    "synthetic transcript rewrite audit append failure".to_string(),
                ));
            }
            let call = self.rewrite_append_calls.fetch_add(1, Ordering::AcqRel) + 1;
            if self.fail_rewrite_append_call.load(Ordering::Acquire) == call {
                return Err(EventStoreError::Store(
                    "synthetic transcript rewrite audit append failure".to_string(),
                ));
            }
            let incoming_summary = final_assistant_text.map(ToOwned::to_owned);
            let mut all_events = self.events.lock().await;
            let session_events = all_events.entry(session_id.clone()).or_default();
            let exact: Vec<_> = session_events
                .iter()
                .filter(|stored| match &stored.event {
                    AgentEvent::TranscriptRewriteAuditReceiptCommitted {
                        session_id: stored_session_id,
                        receipt: stored_receipt,
                        ..
                    } => stored_session_id == session_id && stored_receipt == receipt,
                    _ => false,
                })
                .cloned()
                .collect();
            match exact.as_slice() {
                [] => {
                    let stored = StoredEvent {
                        seq: session_events.len() as u64 + 1,
                        schema_version: EVENT_SCHEMA_VERSION,
                        timestamp: meerkat_core::time_compat::SystemTime::now(),
                        source: meerkat_core::event::EventSourceIdentity::session(
                            session_id.clone(),
                        ),
                        mob_id: None,
                        stream_seq: 0,
                        event: AgentEvent::TranscriptRewriteAuditReceiptCommitted {
                            session_id: session_id.clone(),
                            receipt: receipt.clone(),
                            final_assistant_text: incoming_summary,
                        },
                    };
                    session_events.push(stored.clone());
                    drop(all_events);
                    self.notify.notify_waiters();
                    Ok(crate::event_store::ExactTranscriptRewriteReceiptAppend::Inserted(stored))
                }
                [stored] => {
                    let stored_summary = match &stored.event {
                        AgentEvent::TranscriptRewriteAuditReceiptCommitted {
                            final_assistant_text,
                            ..
                        } => final_assistant_text,
                        _ => unreachable!("exact receipt filter changed event variant"),
                    };
                    if stored_summary.as_deref() == incoming_summary.as_deref() {
                        Ok(
                            crate::event_store::ExactTranscriptRewriteReceiptAppend::Replayed(
                                stored.clone(),
                            ),
                        )
                    } else {
                        Err(EventStoreError::ExactTranscriptRewriteReceiptConflict {
                            session_id: session_id.clone(),
                            existing_count: 1,
                            reason: format!(
                                "row {} carries a different terminal assistant-text projection",
                                stored.seq
                            ),
                        })
                    }
                }
                duplicates => Err(EventStoreError::ExactTranscriptRewriteReceiptConflict {
                    session_id: session_id.clone(),
                    existing_count: duplicates.len(),
                    reason: "multiple exact receipt rows".to_string(),
                }),
            }
        }

        async fn record_projection_halt(
            &self,
            session_id: &SessionId,
            reason: &str,
        ) -> Result<(), EventStoreError> {
            self.projection_halts.lock().await.insert(
                session_id.clone(),
                crate::event_store::EventProjectionHaltMarker {
                    session_id: session_id.clone(),
                    reason: reason.to_string(),
                    recorded_at: meerkat_core::time_compat::SystemTime::now(),
                },
            );
            Ok(())
        }

        async fn projection_halt(
            &self,
            session_id: &SessionId,
        ) -> Result<Option<crate::event_store::EventProjectionHaltMarker>, EventStoreError>
        {
            Ok(self.projection_halts.lock().await.get(session_id).cloned())
        }

        async fn append_interaction_terminal_exact(
            &self,
            session_id: &SessionId,
            interaction_id: meerkat_core::interaction::InteractionId,
            envelope: &meerkat_core::event::EventEnvelope<AgentEvent>,
        ) -> Result<ExactInteractionAppend, EventStoreError> {
            crate::event_store::validate_exact_interaction_terminal(interaction_id, envelope)?;
            if self.fail_appends.load(Ordering::Acquire) {
                return Err(EventStoreError::Store(
                    "synthetic transcript rewrite audit append failure".to_string(),
                ));
            }
            let mut all_events = self.events.lock().await;
            let session_events = all_events.entry(session_id.clone()).or_default();
            let exact_rows: Vec<_> = session_events
                .iter()
                .filter(|row| {
                    matches!(
                        row.source,
                        meerkat_core::event::EventSourceIdentity::Interaction {
                            interaction_id: source_id
                        } if source_id == interaction_id
                    )
                })
                .cloned()
                .collect();
            match exact_rows.as_slice() {
                [] => {
                    let stored = StoredEvent {
                        seq: session_events.len() as u64 + 1,
                        schema_version: EVENT_SCHEMA_VERSION,
                        timestamp: meerkat_core::time_compat::SystemTime::now(),
                        source: envelope.source.clone(),
                        mob_id: envelope.mob_id.clone(),
                        stream_seq: envelope.seq,
                        event: envelope.payload.clone(),
                    };
                    session_events.push(stored.clone());
                    drop(all_events);
                    self.notify.notify_waiters();
                    Ok(ExactInteractionAppend::Inserted(stored))
                }
                [existing]
                    if existing.mob_id == envelope.mob_id
                        && crate::event_store::interaction_terminal_events_semantically_equal(
                            &existing.event,
                            &envelope.payload,
                        ) =>
                {
                    Ok(ExactInteractionAppend::Replayed(existing.clone()))
                }
                rows => Err(EventStoreError::ExactInteractionTerminalConflict {
                    session_id: session_id.clone(),
                    interaction_id,
                    existing_count: rows.len(),
                    reason: "recording store exact interaction terminal conflict".to_string(),
                }),
            }
        }

        async fn append_interaction_terminals_exact_batch(
            &self,
            session_id: &SessionId,
            stream_seq_floor: u64,
            terminals: &[(
                meerkat_core::interaction::InteractionId,
                meerkat_core::event::EventEnvelope<AgentEvent>,
            )],
        ) -> Result<Vec<ExactInteractionAppend>, EventStoreError> {
            crate::event_store::validate_exact_interaction_terminal_batch(terminals)?;
            if terminals.is_empty() {
                return Ok(Vec::new());
            }
            if self.fail_appends.load(Ordering::Acquire) {
                return Err(EventStoreError::Store(
                    "synthetic transcript rewrite audit append failure".to_string(),
                ));
            }
            let mut all_events = self.events.lock().await;
            let session_events = all_events.entry(session_id.clone()).or_default();
            let occupants: Vec<_> = terminals
                .iter()
                .map(|(interaction_id, _)| {
                    let exact: Vec<_> = session_events
                        .iter()
                        .filter(|row| {
                            matches!(
                                row.source,
                                meerkat_core::event::EventSourceIdentity::Interaction {
                                    interaction_id: source_id
                                } if source_id == *interaction_id
                            )
                        })
                        .cloned()
                        .collect();
                    match exact.as_slice() {
                        [] => crate::event_store::ExactInteractionOccupancy::Empty,
                        [stored] => {
                            crate::event_store::ExactInteractionOccupancy::One(stored.clone())
                        }
                        [first, ..] => crate::event_store::ExactInteractionOccupancy::Multiple {
                            first: first.clone(),
                            count: exact.len(),
                        },
                    }
                })
                .collect();
            let prefix_len = crate::event_store::validate_exact_interaction_terminal_replay_prefix(
                session_id, terminals, &occupants,
            )?;
            let mut results = Vec::with_capacity(terminals.len());
            let mut replay_tail = 0_u64;
            for occupant in occupants.iter().take(prefix_len) {
                let crate::event_store::ExactInteractionOccupancy::One(stored) = occupant else {
                    return Err(EventStoreError::Store(
                        "validated replay prefix lost its stored row".to_string(),
                    ));
                };
                replay_tail = stored.stream_seq;
                results.push(ExactInteractionAppend::Replayed(stored.clone()));
            }
            let mut next_stream_seq = stream_seq_floor.max(replay_tail);
            let mut inserted_any = false;
            for (_, envelope) in &terminals[prefix_len..] {
                next_stream_seq = next_stream_seq.checked_add(1).ok_or_else(|| {
                    EventStoreError::InvalidExactInteractionTerminalBatch {
                        reason: "session event stream sequence overflow".to_string(),
                    }
                })?;
                let stored = StoredEvent {
                    seq: session_events.len() as u64 + 1,
                    schema_version: EVENT_SCHEMA_VERSION,
                    timestamp: meerkat_core::time_compat::SystemTime::now(),
                    source: envelope.source.clone(),
                    mob_id: envelope.mob_id.clone(),
                    stream_seq: next_stream_seq,
                    event: envelope.payload.clone(),
                };
                session_events.push(stored.clone());
                results.push(ExactInteractionAppend::Inserted(stored));
                inserted_any = true;
            }
            drop(all_events);
            if inserted_any {
                self.notify.notify_waiters();
            }
            Ok(results)
        }

        async fn read_from(
            &self,
            session_id: &SessionId,
            from_seq: u64,
        ) -> Result<Vec<StoredEvent>, EventStoreError> {
            let all_events = self.events.lock().await;
            Ok(all_events
                .get(session_id)
                .into_iter()
                .flat_map(|events| events.iter())
                .filter(|event| event.seq >= from_seq)
                .cloned()
                .collect())
        }

        async fn last_seq(&self, session_id: &SessionId) -> Result<u64, EventStoreError> {
            let all_events = self.events.lock().await;
            Ok(all_events
                .get(session_id)
                .map_or(0, |events| events.len() as u64))
        }
    }

    struct PausingAppendEventStore {
        inner: RecordingEventStore,
        append_entered: AtomicBool,
        release_append: tokio::sync::Semaphore,
    }

    impl Default for PausingAppendEventStore {
        fn default() -> Self {
            Self {
                inner: RecordingEventStore::default(),
                append_entered: AtomicBool::new(false),
                release_append: tokio::sync::Semaphore::new(0),
            }
        }
    }

    impl PausingAppendEventStore {
        async fn wait_for_append(&self) {
            tokio::time::timeout(std::time::Duration::from_secs(5), async {
                while !self.append_entered.load(Ordering::Acquire) {
                    tokio::task::yield_now().await;
                }
            })
            .await
            .expect("create-time event append did not reach the test gate");
        }

        fn release_append(&self) {
            self.release_append.add_permits(1);
        }
    }

    #[async_trait::async_trait]
    impl EventStore for PausingAppendEventStore {
        async fn append_envelopes(
            &self,
            session_id: &SessionId,
            envelopes: &[meerkat_core::event::EventEnvelope<AgentEvent>],
        ) -> Result<u64, EventStoreError> {
            self.append_entered.store(true, Ordering::Release);
            self.release_append
                .acquire()
                .await
                .map_err(|_| EventStoreError::Store("append gate closed".to_string()))?
                .forget();
            self.inner.append_envelopes(session_id, envelopes).await
        }

        async fn append_transcript_rewrite_receipt_exact(
            &self,
            session_id: &SessionId,
            receipt: &meerkat_core::TranscriptRewriteAuditReceiptBatch,
            final_assistant_text: Option<&str>,
        ) -> Result<crate::event_store::ExactTranscriptRewriteReceiptAppend, EventStoreError>
        {
            self.append_entered.store(true, Ordering::Release);
            self.release_append
                .acquire()
                .await
                .map_err(|_| EventStoreError::Store("append gate closed".to_string()))?
                .forget();
            self.inner
                .append_transcript_rewrite_receipt_exact(session_id, receipt, final_assistant_text)
                .await
        }

        async fn record_projection_halt(
            &self,
            session_id: &SessionId,
            reason: &str,
        ) -> Result<(), EventStoreError> {
            self.inner.record_projection_halt(session_id, reason).await
        }

        async fn projection_halt(
            &self,
            session_id: &SessionId,
        ) -> Result<Option<crate::event_store::EventProjectionHaltMarker>, EventStoreError>
        {
            self.inner.projection_halt(session_id).await
        }

        async fn read_from(
            &self,
            session_id: &SessionId,
            from_seq: u64,
        ) -> Result<Vec<StoredEvent>, EventStoreError> {
            self.inner.read_from(session_id, from_seq).await
        }

        async fn last_seq(&self, session_id: &SessionId) -> Result<u64, EventStoreError> {
            self.inner.last_seq(session_id).await
        }
    }

