    #[tokio::test]
    async fn runtime_snapshot_corruption_remains_typed_serialization() {
        let gated = Arc::new(GatedSnapshotRuntimeStore::new());
        let runtime_id = LogicalRuntimeId::for_session(&SessionId::new());
        gated
            .override_session_snapshot(runtime_id.clone(), b"{ not a serialized Session".to_vec())
            .await;
        let runtime_store: Arc<dyn RuntimeStore> = gated;

        let error = PersistentSessionService::<DummyBuilder>::load_runtime_session_snapshot(
            &runtime_store,
            &runtime_id,
        )
        .await
        .expect_err("malformed runtime snapshot bytes must fail decode");
        match error {
            SessionError::Store(source) => assert!(
                matches!(
                    source.downcast_ref::<SessionStoreError>(),
                    Some(SessionStoreError::Serialization(_))
                ),
                "malformed runtime snapshot bytes must remain a typed serialization error, got {source:?}"
            ),
            other => panic!("expected typed SessionError::Store, got {other:?}"),
        }
    }

    #[tokio::test]
    async fn runtime_snapshot_transport_failure_remains_internal_and_distinct() {
        let gated = Arc::new(GatedSnapshotRuntimeStore::new());
        gated.set_fail_snapshot_loads(true);
        let runtime_store: Arc<dyn RuntimeStore> = gated;
        let runtime_id = LogicalRuntimeId::for_session(&SessionId::new());

        let error = PersistentSessionService::<DummyBuilder>::load_runtime_session_snapshot(
            &runtime_store,
            &runtime_id,
        )
        .await
        .expect_err("transport failure must fail runtime snapshot load");
        assert!(
            matches!(error, SessionError::Agent(AgentError::InternalError(_))),
            "RuntimeStore transport failure must remain distinct from persisted serialization corruption, got {error:?}"
        );
    }

    fn test_transient_turn_context_state_handle() -> meerkat_core::TransientTurnContextStateHandle {
        meerkat_core::TransientTurnContextStateHandle::new()
    }

    struct DummyAgent {
        session: Arc<std::sync::Mutex<Session>>,
        transient_turn_context_state: meerkat_core::TransientTurnContextStateHandle,
        run_failure: Option<String>,
        flow_overlay_failure: Option<String>,
        callback_pending_after_run: bool,
        execution_snapshot: Option<meerkat_core::AgentExecutionSnapshot>,
        compaction_abort_failure: Option<String>,
    }

    #[async_trait::async_trait]
    impl SessionAgent for DummyAgent {
        async fn run_with_events(
            &mut self,
            prompt: meerkat_core::types::ContentInput,
            _event_tx: tokio::sync::mpsc::Sender<meerkat_core::event::AgentEvent>,
        ) -> Result<RunResult, meerkat_core::error::AgentError> {
            if let Some(message) = self.run_failure.clone() {
                if self
                    .execution_snapshot
                    .as_ref()
                    .is_some_and(|snapshot| snapshot.turn_terminal)
                {
                    let mut session = self
                        .session
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner);
                    session.push(meerkat_core::types::Message::User(
                        meerkat_core::types::UserMessage::text(prompt.text_content()),
                    ));
                }
                return Err(meerkat_core::error::AgentError::InternalError(message));
            }
            let session_id = self.session_id();
            let result = {
                let mut session = match self.session.lock() {
                    Ok(guard) => guard,
                    Err(poisoned) => poisoned.into_inner(),
                };
                session.push(meerkat_core::types::Message::User(
                    meerkat_core::types::UserMessage::text(prompt.text_content()),
                ));
                session.push(meerkat_core::types::Message::BlockAssistant(
                    meerkat_core::types::BlockAssistantMessage {
                        blocks: vec![meerkat_core::types::AssistantBlock::Text {
                            text: "ok".to_string(),
                            meta: None,
                        }],
                        stop_reason: meerkat_core::types::StopReason::EndTurn,
                        identity: meerkat_core::types::TranscriptMessageIdentity::default(),
                        created_at: meerkat_core::types::message_timestamp_now(),
                    },
                ));
                RunResult {
                    text: "ok".to_string(),
                    session_id,
                    usage: meerkat_core::types::Usage::default(),
                    turns: 1,
                    tool_calls: 0,
                    terminal_cause_kind: None,
                    structured_output: None,
                    extraction_error: None,
                    schema_warnings: None,
                    skill_diagnostics: None,
                }
            };
            if self.callback_pending_after_run {
                return Err(meerkat_core::error::AgentError::CallbackPending {
                    tool_use_id: "test-call".to_string(),
                    tool_name: "test_callback".to_string(),
                    args: serde_json::json!({}),
                });
            }
            Ok(result)
        }

        async fn abort_uncommitted_compaction_projections(
            &mut self,
        ) -> Result<(), meerkat_core::error::AgentError> {
            match self.compaction_abort_failure.take() {
                Some(message) => Err(meerkat_core::error::AgentError::InternalError(message)),
                None => Ok(()),
            }
        }

        fn take_runtime_terminal_failure_witness(
            &mut self,
        ) -> Result<Option<meerkat_core::TurnErrorMetadata>, meerkat_core::error::AgentError>
        {
            let Some(snapshot) = self.execution_snapshot.as_ref() else {
                return Ok(None);
            };
            if !snapshot.turn_terminal {
                return Ok(None);
            }
            let Some(cause_kind) = snapshot.terminal_cause_kind else {
                return Err(meerkat_core::error::AgentError::InternalError(
                    "dummy terminal snapshot omitted cause".to_string(),
                ));
            };
            Ok(Some(meerkat_core::TurnErrorMetadata::terminal(
                cause_kind,
                snapshot.terminal_outcome,
                self.run_failure
                    .clone()
                    .unwrap_or_else(|| "dummy terminal failure".to_string()),
            )))
        }

        fn set_skill_references(&mut self, _refs: Option<Vec<meerkat_core::skills::SkillKey>>) {}

        fn set_turn_tool_overlay(
            &mut self,
            _overlay: Option<meerkat_core::service::TurnToolOverlay>,
        ) -> Result<(), meerkat_core::error::AgentError> {
            if let Some(message) = self.flow_overlay_failure.clone() {
                return Err(meerkat_core::error::AgentError::InternalError(message));
            }
            Ok(())
        }

        fn cancel(&mut self) {}

        fn hot_swap_llm_identity(
            &mut self,
            _client: Arc<dyn meerkat_core::AgentLlmClient>,
            identity: meerkat_core::SessionLlmIdentity,
            _request_policy: meerkat_core::SessionLlmRequestPolicy,
        ) -> Result<(), meerkat_core::error::AgentError> {
            let mut session = match self.session.lock() {
                Ok(guard) => guard,
                Err(poisoned) => poisoned.into_inner(),
            };
            let mut metadata =
                session
                    .session_metadata()
                    .unwrap_or(meerkat_core::SessionMetadata {
                        schema_version: meerkat_core::SESSION_METADATA_SCHEMA_VERSION,
                        model: identity.model.clone(),
                        max_tokens: 0,
                        structured_output_retries: 2,
                        provider: identity.provider,
                        self_hosted_server_id: None,
                        provider_params: identity.provider_params.clone(),
                        tooling: meerkat_core::SessionTooling::default(),
                        keep_alive: false,
                        comms_name: None,
                        peer_meta: None,
                        realm_id: None,
                        instance_id: None,
                        backend: None,
                        config_generation: None,
                        auth_binding: None,
                        mob_member_binding: None,
                    });
            metadata.apply_llm_identity(&identity);
            session.set_session_metadata(metadata).map_err(|err| {
                meerkat_core::error::AgentError::InternalError(format!(
                    "failed to update dummy session metadata: {err}"
                ))
            })
        }

        fn stage_external_tool_filter(
            &mut self,
            filter: meerkat_core::ToolFilter,
        ) -> Result<(), meerkat_core::error::AgentError> {
            let mut state = {
                let session = match self.session.lock() {
                    Ok(guard) => guard,
                    Err(poisoned) => poisoned.into_inner(),
                };
                session
                    .tool_visibility_state()
                    .map_err(|err| {
                        meerkat_core::error::AgentError::InternalError(format!(
                            "failed to decode dummy visibility state: {err}"
                        ))
                    })?
                    .unwrap_or_default()
            };
            state.staged_filter = filter;
            state.staged_revision = state.staged_revision.max(state.active_revision) + 1;
            self.set_tool_visibility_state(Some(state))
        }

        fn set_tool_visibility_state(
            &mut self,
            state: Option<meerkat_core::SessionToolVisibilityState>,
        ) -> Result<(), meerkat_core::error::AgentError> {
            let _ = state;
            Ok(())
        }

        fn session_id(&self) -> SessionId {
            match self.session.lock() {
                Ok(guard) => guard.id().clone(),
                Err(poisoned) => poisoned.into_inner().id().clone(),
            }
        }

        fn snapshot(&self) -> SessionSnapshot {
            let session = match self.session.lock() {
                Ok(guard) => guard,
                Err(poisoned) => poisoned.into_inner(),
            };
            SessionSnapshot {
                created_at: session.created_at(),
                updated_at: session.updated_at(),
                message_count: session.messages().len(),
                total_tokens: session.total_tokens(),
                usage: session.total_usage(),
                last_assistant_text: session.last_assistant_text(),
            }
        }

        fn execution_snapshot(
            &self,
        ) -> Result<
            Option<meerkat_core::AgentExecutionSnapshot>,
            meerkat_core::SnapshotProjectionError,
        > {
            Ok(self.execution_snapshot.clone())
        }

        fn session_clone(&self) -> Result<Session, AgentError> {
            match self.session.lock() {
                Ok(guard) => Ok(guard.clone()),
                Err(poisoned) => Ok(poisoned.into_inner().clone()),
            }
        }

        fn durable_llm_identity(&self) -> Option<meerkat_core::SessionLlmIdentity> {
            let session = match self.session.lock() {
                Ok(guard) => guard,
                Err(poisoned) => poisoned.into_inner(),
            };
            Some(test_durable_llm_identity(&session))
        }

        fn observed_session_tail(&self) -> ObservedSessionTailKind {
            let session = match self.session.lock() {
                Ok(guard) => guard,
                Err(poisoned) => poisoned.into_inner(),
            };
            meerkat_core::pending_continuation::observe_session_tail(session.messages())
        }

        fn update_keep_alive(&mut self, keep_alive: bool) {
            let mut session = match self.session.lock() {
                Ok(guard) => guard,
                Err(poisoned) => poisoned.into_inner(),
            };
            if let Some(mut meta) = session.session_metadata() {
                meta.keep_alive = keep_alive;
                let _ = session.set_session_metadata(meta);
            }
        }

        fn update_mob_tool_authority_context(
            &mut self,
            authority_context: Option<MobToolAuthorityContext>,
        ) -> Result<(), meerkat_core::error::AgentError> {
            let mut session = match self.session.lock() {
                Ok(guard) => guard,
                Err(poisoned) => poisoned.into_inner(),
            };
            session
                .set_mob_tool_authority_context(authority_context)
                .map_err(|err| {
                    meerkat_core::error::AgentError::InternalError(format!(
                        "failed to update dummy mob authority context: {err}"
                    ))
                })
        }

        fn append_system_messages(
            &mut self,
            contents: Vec<String>,
        ) -> Result<(), meerkat_core::error::AgentError> {
            let mut session = match self.session.lock() {
                Ok(guard) => guard,
                Err(poisoned) => poisoned.into_inner(),
            };
            for content in contents {
                session.append_system_message(content);
            }
            Ok(())
        }

        fn transient_turn_context_state(&self) -> meerkat_core::TransientTurnContextStateHandle {
            self.transient_turn_context_state.clone()
        }

        fn sync_session_from_durable_snapshot(
            &mut self,
            session: Session,
        ) -> Result<(), meerkat_core::error::AgentError> {
            if session.id() != &self.session_id() {
                return Err(meerkat_core::error::AgentError::InternalError(format!(
                    "durable snapshot session id {} does not match live session {}",
                    session.id(),
                    self.session_id()
                )));
            }
            match self.session.lock() {
                Ok(mut guard) => {
                    *guard = session;
                }
                Err(poisoned) => {
                    *poisoned.into_inner() = session;
                }
            }
            Ok(())
        }
    }

