    #[tokio::test]
    async fn test_persistent_rewrite_transcript_appends_audit_event() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let event_store = Arc::new(RecordingEventStore::default());
        let event_store_trait: Arc<dyn EventStore> = event_store.clone();
        let dir = tempfile::tempdir().expect("tempdir");
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        )
        .with_event_projection(
            event_store_trait,
            Arc::new(SessionProjector::new(dir.path().join(".rkat"))),
        );

        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create_session should succeed");
        let session_id = created.session_id;
        committed_content_turn(&service, runtime_store.as_ref(), &session_id, "hello").await;
        let parent_revision = service
            .load_authoritative_session(&session_id)
            .await
            .expect("load before rewrite")
            .expect("session exists")
            .transcript_revision()
            .expect("parent revision");

        let rewrite = service
            .rewrite_session_transcript(
                &session_id,
                meerkat_core::SessionTranscriptRewriteRequest {
                    selection: TranscriptRewriteSelection::MessageRange { start: 1, end: 2 },
                    replacement: vec![Message::BlockAssistant(
                        meerkat_core::BlockAssistantMessage::new(
                            vec![meerkat_core::AssistantBlock::Text {
                                text: "audit compacted trace".to_string(),
                                meta: None,
                            }],
                            StopReason::EndTurn,
                        ),
                    )],
                    reason: TranscriptRewriteReason::new("compaction"),
                    actor: Some("audit-test".to_string()),
                    expected_parent_revision: Some(parent_revision.clone()),
                    running_behavior: TranscriptEditRunningBehavior::Reject,
                },
            )
            .await
            .expect("rewrite should commit");

        let events = service
            .event_log_read_from(&session_id, 1)
            .await
            .expect("event log should read")
            .expect("event projection installed");
        let audit = events
            .iter()
            .find_map(|stored| match &stored.event {
                AgentEvent::TranscriptRewriteAuditReceiptCommitted {
                    session_id,
                    receipt,
                    ..
                } => Some((session_id, receipt)),
                _ => None,
            })
            .expect("rewrite audit receipt should be appended");
        assert_eq!(audit.0, &session_id);
        assert_eq!(audit.1.commits().len(), 1);
        assert_eq!(audit.1.commits()[0].parent_revision, parent_revision);
        assert_eq!(audit.1.commits()[0].revision, rewrite.revision);
        assert_eq!(audit.1.commits()[0].reason.kind, "compaction");
        assert!(
            events.iter().all(|stored| !matches!(
                stored.event,
                AgentEvent::TranscriptRewriteCommitted { .. }
            )),
            "current writers must not emit full-body rewrite events"
        );
        let durable = store
            .load(&session_id)
            .await
            .expect("load durable rewrite")
            .expect("rewritten session exists");
        let graph = durable
            .validated_transcript_history_state()
            .expect("durable graph should validate")
            .expect("durable graph should exist");
        let proved = graph
            .prove_commit_suffix_starting_with(&audit.1.commits()[0])
            .expect("receipt commit should select a sealed graph suffix");
        assert_eq!(proved.start_prefix(), audit.1.start_prefix());
        assert_eq!(proved.end_prefix(), audit.1.end_prefix());
        assert_eq!(
            serde_json::to_value(durable.messages()).expect("durable head serializes"),
            serde_json::to_value(
                &service
                    .read_history(&session_id, SessionHistoryQuery::default())
                    .await
                    .expect("history after rewrite")
                    .messages
            )
            .expect("history serializes")
        );

        let events_path = dir
            .path()
            .join(".rkat")
            .join("sessions")
            .join(session_id.to_string())
            .join("events.jsonl");
        let projected =
            read_projected_events_after(&events_path, "transcript_rewrite_audit_receipt_committed")
                .await;
        assert!(projected.contains(&rewrite.revision));
    }

    #[tokio::test]
    async fn test_persistent_rewrite_receipt_failure_is_committed_pending() {
        let store: Arc<dyn SessionStore> = Arc::new(MemoryStore::new());
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let event_store = Arc::new(RecordingEventStore::default());
        let event_store_trait: Arc<dyn EventStore> = event_store.clone();
        let dir = tempfile::tempdir().expect("tempdir");
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        )
        .with_event_projection(
            event_store_trait,
            Arc::new(SessionProjector::new(dir.path().join(".rkat"))),
        );

        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create_session should succeed");
        let session_id = created.session_id;
        committed_content_turn(&service, runtime_store.as_ref(), &session_id, "hello").await;
        let parent_revision = service
            .load_authoritative_session(&session_id)
            .await
            .expect("load before rewrite")
            .expect("session exists")
            .transcript_revision()
            .expect("parent revision");

        event_store.fail_appends();
        let rewrite_err = service
            .rewrite_session_transcript(
                &session_id,
                meerkat_core::SessionTranscriptRewriteRequest {
                    selection: TranscriptRewriteSelection::MessageRange { start: 1, end: 2 },
                    replacement: vec![Message::BlockAssistant(
                        meerkat_core::BlockAssistantMessage {
                            blocks: vec![meerkat_core::AssistantBlock::Text {
                                text: "compact answer despite audit outage".to_string(),
                                meta: None,
                            }],
                            stop_reason: StopReason::EndTurn,
                            identity: meerkat_core::types::TranscriptMessageIdentity::default(),
                            created_at: meerkat_core::types::message_timestamp_now(),
                        },
                    )],
                    reason: TranscriptRewriteReason::new("compaction"),
                    actor: Some("audit-failure-test".to_string()),
                    expected_parent_revision: Some(parent_revision),
                    running_behavior: TranscriptEditRunningBehavior::Reject,
                },
            )
            .await
            .expect_err(
                "rewrite must fail closed when the canonical audit event cannot be appended",
            );
        assert!(
            rewrite_err
                .to_string()
                .contains("synthetic transcript rewrite audit append failure"),
            "unexpected error: {rewrite_err}"
        );
        let stored = store
            .load(&session_id)
            .await
            .expect("SessionStore load after failed receipt append")
            .expect("committed projection remains present");
        assert!(matches!(
            &stored.messages()[1],
            Message::BlockAssistant(assistant)
                if assistant.to_string() == "compact answer despite audit outage"
        ));
        let runtime_id =
            PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&session_id);
        let runtime_bytes = runtime_store
            .load_session_snapshot(&runtime_id)
            .await
            .expect("RuntimeStore load after failed receipt append")
            .expect("committed RuntimeStore authority remains present");
        let runtime_session =
            Session::from_persisted_bytes(&runtime_bytes).expect("runtime authority should decode");
        assert_eq!(
            runtime_session.transcript_revision().unwrap(),
            stored.transcript_revision().unwrap(),
            "receipt failure must not roll back either committed authority or its projection"
        );
        assert!(
            event_store
                .read_from(&session_id, 1)
                .await
                .unwrap()
                .iter()
                .all(|stored| !matches!(
                    stored.event,
                    AgentEvent::TranscriptRewriteAuditReceiptCommitted { .. }
                )),
            "the failed receipt must remain pending rather than being reported as durable"
        );
    }

    #[tokio::test]
    async fn test_persistent_rewrite_projection_failure_is_committed_pending_and_repairable() {
        let projection_store = Arc::new(FailSaveStore::new());
        let store: Arc<dyn SessionStore> = Arc::clone(&projection_store) as Arc<dyn SessionStore>;
        let runtime_store: Arc<dyn RuntimeStore> = Arc::new(InMemoryRuntimeStore::new());
        let event_store = Arc::new(RecordingEventStore::default());
        let event_store_trait: Arc<dyn EventStore> = event_store.clone();
        let dir = tempfile::tempdir().expect("tempdir");
        let service = PersistentSessionService::new(
            DummyBuilder,
            4,
            Arc::clone(&store),
            Arc::clone(&runtime_store),
            memory_blob_store(),
        )
        .with_event_projection(
            event_store_trait,
            Arc::new(SessionProjector::new(dir.path().join(".rkat"))),
        );

        let created = service
            .create_session(create_request("seed", InitialTurnPolicy::Defer))
            .await
            .expect("create_session should succeed");
        let session_id = created.session_id;
        committed_content_turn(&service, runtime_store.as_ref(), &session_id, "hello").await;
        let projected_before = store
            .load(&session_id)
            .await
            .expect("load projection before rewrite")
            .expect("projection exists");
        let projected_before_revision = projected_before
            .transcript_revision()
            .expect("projected revision");

        projection_store.set_fail_save(true);
        let error = service
            .rewrite_session_transcript(
                &session_id,
                meerkat_core::SessionTranscriptRewriteRequest {
                    selection: TranscriptRewriteSelection::MessageRange { start: 1, end: 2 },
                    replacement: vec![Message::BlockAssistant(
                        meerkat_core::BlockAssistantMessage::new(
                            vec![meerkat_core::AssistantBlock::Text {
                                text: "committed while projection is unavailable".to_string(),
                                meta: None,
                            }],
                            StopReason::EndTurn,
                        ),
                    )],
                    reason: TranscriptRewriteReason::new("compaction"),
                    actor: Some("projection-failure-test".to_string()),
                    expected_parent_revision: Some(projected_before_revision.clone()),
                    running_behavior: TranscriptEditRunningBehavior::Reject,
                },
            )
            .await
            .expect_err("projection outage must report committed-pending");
        assert!(
            error.to_string().contains("forced save failure"),
            "unexpected projection error: {error}"
        );

        let runtime_id =
            PersistentSessionService::<DummyBuilder>::runtime_id_for_session(&session_id);
        let runtime_bytes = runtime_store
            .load_session_snapshot(&runtime_id)
            .await
            .expect("load committed runtime authority")
            .expect("runtime authority exists");
        let runtime_session =
            Session::from_persisted_bytes(&runtime_bytes).expect("runtime authority decodes");
        let committed_revision = runtime_session
            .transcript_revision()
            .expect("committed rewrite revision");
        assert_ne!(committed_revision, projected_before_revision);
        assert_eq!(
            store
                .load(&session_id)
                .await
                .expect("load lagging projection")
                .expect("lagging projection remains")
                .transcript_revision()
                .expect("lagging projection revision"),
            projected_before_revision,
            "a failed downstream projection must not pretend to have committed"
        );
        assert_eq!(
            event_store.rewrite_append_calls.load(Ordering::Acquire),
            0,
            "receipt publication must wait for the rebuildable projection"
        );

        projection_store.set_fail_save(false);
        service
            .checkpoint_committed_runtime_session_snapshot(
                &session_id,
                Arc::new(runtime_bytes.clone()),
            )
            .await
            .expect("exact committed runtime bytes should repair projection and receipt");
        assert_eq!(
            store
                .load(&session_id)
                .await
                .expect("load repaired projection")
                .expect("repaired projection exists")
                .transcript_revision()
                .expect("repaired projection revision"),
            committed_revision
        );
        let receipt_rows = event_store
            .read_from(&session_id, 1)
            .await
            .expect("read repaired receipt")
            .into_iter()
            .filter(|stored| {
                matches!(
                    stored.event,
                    AgentEvent::TranscriptRewriteAuditReceiptCommitted { .. }
                )
            })
            .count();
        assert_eq!(receipt_rows, 1, "repair must publish one exact receipt");
    }

